import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.CnTYizyl.js";const _=JSON.parse('{"title":"零基础部署 VitePress 真实踩坑复盘","description":"","frontmatter":{},"headers":[],"relativePath":"tech/post2.md","filePath":"tech/post2.md"}'),s={name:"tech/post2.md"};function i(n,e,d,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="零基础部署-vitepress-真实踩坑复盘" tabindex="-1">零基础部署 VitePress 真实踩坑复盘 <a class="header-anchor" href="#零基础部署-vitepress-真实踩坑复盘" aria-label="Permalink to &quot;零基础部署 VitePress 真实踩坑复盘&quot;">​</a></h1><p>事实上，有关于这个作品，极大程度上都是依赖于ai的，作为一个零基础学生，这次的博客部署过程远比写代码本身艰难。但即使在AI辅助下面，我依然发现了一些困境，以下是总结。</p><h2 id="_1-本地环境权限报错" tabindex="-1">1. 本地环境权限报错 <a class="header-anchor" href="#_1-本地环境权限报错" aria-label="Permalink to &quot;1. 本地环境权限报错&quot;">​</a></h2><p>在 Windows PowerShell 中运行命令时遭遇 <code>UnauthorizedAccess</code>。 <strong>解决</strong>：切换至 Command Prompt (CMD) 绕过权限限制。</p><h2 id="_2-github-网络阻断" tabindex="-1">2. GitHub 网络阻断 <a class="header-anchor" href="#_2-github-网络阻断" aria-label="Permalink to &quot;2. GitHub 网络阻断&quot;">​</a></h2><p>尝试推送到 GitHub 时遭遇 <code>ERR_CONNECTION_RESET</code>，无法连接。 <strong>解决</strong>：果断切换至 Gitee 平台完成代码托管，保障进度。</p><h2 id="_3-gitee-pages-个人服务下线" tabindex="-1">3. Gitee Pages 个人服务下线 <a class="header-anchor" href="#_3-gitee-pages-个人服务下线" aria-label="Permalink to &quot;3. Gitee Pages 个人服务下线&quot;">​</a></h2><p>准备部署时发现 Gitee Pages 个人版已不可用。 <strong>解决</strong>：尝试 Netlify 替代，但因网络风控无法注册。</p><h2 id="_4-腾讯云-edgeone-部署与路径修复" tabindex="-1">4. 腾讯云 EdgeOne 部署与路径修复 <a class="header-anchor" href="#_4-腾讯云-edgeone-部署与路径修复" aria-label="Permalink to &quot;4. 腾讯云 EdgeOne 部署与路径修复&quot;">​</a></h2><p>最终采用腾讯云 EdgeOne 部署。 <strong>解决</strong>：页面样式丢失后，排查出 <code>base</code> 路径与 EdgeOne 根目录层级冲突，修改配置重新构建，最终公网访问成功。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>虽然ai在这个时代能辅助甚至代替计算机学生进行一些代码性的操作，但在实际过程中所面临的问题却远远不止复制粘贴。但在使用ai的同时，我们也意识到算法本身的神奇，又或者一些代码在实际应用上的理解，我认为这是对于一个在AI时代下零基础学生所能做的，或者说所能学习的课题.而更加令人感到愉悦的是,ai本身就是代码跑出来的</p>',12)])])}const g=a(s,[["render",i]]);export{_ as __pageData,g as default};
